package messageblocks

import (
	"encoding/json"
	"testing"
)

// TestParseBlocksMatchesZod uses accept/reject fixtures generated by running
// MessageBlockSchema (packages/contracts/src/threads/message-blocks.ts) with zod:
//
//	node_modules/.bin/tsx /tmp/zod-fixtures.mts
//
// The expected booleans below are that script's output. Each case is parsed as a
// one-entry list, except the two `list-` cases, because MessageBlock.array() is how
// the cancel path reads stored blocks.
func TestParseBlocksMatchesZod(t *testing.T) {
	cases := map[string]struct {
		json string
		want bool
	}{
		"cred-login-https":           {`{"kind":"ask","text":"Sign in","credential":{"name":"site_login","origin":"https://www.example.test","auth":{"type":"login"}}}`, true},
		"cred-login-http":            {`{"kind":"ask","text":"Sign in","credential":{"name":"site_login","origin":"http://www.example.test","auth":{"type":"login"}}}`, false},
		"cred-login-private-http":    {`{"kind":"ask","text":"Sign in","credential":{"name":"site_login","origin":"http://192.168.1.5","auth":{"type":"login"}}}`, false},
		"cred-login-path":            {`{"kind":"ask","text":"Sign in","credential":{"name":"site_login","origin":"https://www.example.test/login","auth":{"type":"login"}}}`, false},
		"cred-bearer":                {`{"kind":"ask","text":"Key","credential":{"name":"site_key","origin":"https://www.example.test","auth":{"type":"bearer"}}}`, true},
		"cred-header-host":           {`{"kind":"ask","text":"Key","credential":{"name":"site_key","origin":"https://www.example.test","auth":{"type":"header","name":"Host"}}}`, false},
		"cred-basic-bad-user":        {`{"kind":"ask","text":"Key","credential":{"name":"site_key","origin":"https://www.example.test","auth":{"type":"basic","username":"a:b"}}}`, false},
		"cred-command":               {`{"kind":"ask","text":"Env","credential":{"name":"netbird-key","origin":"","auth":{"type":"command"}}}`, true},
		"cred-command-origin":        {`{"kind":"ask","text":"Env","credential":{"name":"netbird-key","origin":"https://www.example.test","auth":{"type":"command"}}}`, false},
		"cred-command-reserved":      {`{"kind":"ask","text":"Env","credential":{"name":"path","origin":"","auth":{"type":"command"}}}`, false},
		"cred-card":                  {`{"kind":"ask","text":"Card","credential":{"name":"card","origin":"","auth":{"type":"card"}}}`, true},
		"cred-contact":               {`{"kind":"ask","text":"Contact","credential":{"name":"contact","origin":"","auth":{"type":"contact"}}}`, true},
		"cred-bad-name":              {`{"kind":"ask","text":"Key","credential":{"name":"Site","origin":"https://www.example.test","auth":{"type":"bearer"}}}`, false},
		"cred-missing-origin-bearer": {`{"kind":"ask","text":"Key","credential":{"name":"site_key","auth":{"type":"bearer"}}}`, false},
		"cred-bearer-private-http":   {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"http://192.168.1.5","auth":{"type":"bearer"}}}`, true},
		"cred-bearer-http-public":    {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"http://www.example.test","auth":{"type":"bearer"}}}`, false},
		"cred-bearer-metadata-ip":    {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"http://169.254.169.254","auth":{"type":"bearer"}}}`, false},
		"cred-bearer-metadata-name":  {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://metadata.google.internal","auth":{"type":"bearer"}}}`, false},
		"cred-bearer-metadata-dot":   {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://metadata.google.internal.","auth":{"type":"bearer"}}}`, false},
		"cred-bearer-localhost-dot":  {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"http://localhost.","auth":{"type":"bearer"}}}`, false},
		"cred-bearer-localhost":      {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"http://localhost","auth":{"type":"bearer"}}}`, true},
		"cred-bearer-v6-loop":        {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"http://[::1]","auth":{"type":"bearer"}}}`, true},
		"cred-bearer-v6-ula":         {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"http://[fd00::1]","auth":{"type":"bearer"}}}`, true},
		"cred-bearer-port":           {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://www.example.test:8443","auth":{"type":"bearer"}}}`, true},
		"cred-header-host-lower":     {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://www.example.test","auth":{"type":"header","name":"host"}}}`, false},
		"cred-basic-ok":              {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://www.example.test","auth":{"type":"basic","username":"user"}}}`, true},
		"cred-auth-unknown":          {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://www.example.test","auth":{"type":"nope"}}}`, false},
		"cred-origin-null":           {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":null,"auth":{"type":"bearer"}}}`, false},
		"origin-trailing-space":      {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://www.example.test ","auth":{"type":"bearer"}}}`, true},
		"origin-leading-space":       {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":" https://www.example.test","auth":{"type":"bearer"}}}`, true},
		"origin-tab":                 {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://www.example.test\t","auth":{"type":"bearer"}}}`, true},
		"origin-newline":             {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://www.exa\nmple.test","auth":{"type":"bearer"}}}`, true},
		"origin-backslash":           {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https:\\www.example.test","auth":{"type":"bearer"}}}`, true},
		"origin-double-backslash":    {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https:\\\\www.example.test","auth":{"type":"bearer"}}}`, true},
		"origin-single-slash":        {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https:/www.example.test","auth":{"type":"bearer"}}}`, true},
		"origin-dot-path":            {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://www.example.test/.","auth":{"type":"bearer"}}}`, true},
		"origin-dotdot-path":         {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://www.example.test/..","auth":{"type":"bearer"}}}`, true},
		"origin-a-dotdot-path":       {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://www.example.test/a/..","auth":{"type":"bearer"}}}`, true},
		"origin-percent-dot":         {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://www.example.test/%2e","auth":{"type":"bearer"}}}`, true},
		"origin-percent-dotdot":      {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://www.example.test/%2E%2E/","auth":{"type":"bearer"}}}`, true},
		"origin-a-percent-dotdot":    {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://www.example.test/a/%2e%2e/","auth":{"type":"bearer"}}}`, true},
		"origin-above-root":          {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://www.example.test/a/../..","auth":{"type":"bearer"}}}`, true},
		"origin-double-slash-path":   {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://www.example.test//","auth":{"type":"bearer"}}}`, false},
		"origin-query-empty":         {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://www.example.test?","auth":{"type":"bearer"}}}`, true},
		"origin-fragment-empty":      {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://www.example.test#","auth":{"type":"bearer"}}}`, true},
		"origin-both-empty":          {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://www.example.test?#","auth":{"type":"bearer"}}}`, true},
		"origin-empty-port":          {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://www.example.test:","auth":{"type":"bearer"}}}`, true},
		"origin-big-port":            {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://www.example.test:99999","auth":{"type":"bearer"}}}`, false},
		"origin-trailing-dot":        {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://example.com.","auth":{"type":"bearer"}}}`, true},
		"origin-short-ipv4":          {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"http://127.1","auth":{"type":"bearer"}}}`, true},
		"origin-octal-ipv4":          {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"http://0177.0.0.1","auth":{"type":"bearer"}}}`, true},
		"origin-hex-ipv4":            {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"http://0x7f.0.0.1","auth":{"type":"bearer"}}}`, true},
		"origin-integer-ipv4":        {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"http://2130706433","auth":{"type":"bearer"}}}`, true},
		"origin-mapped-private":      {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"http://[::ffff:192.168.1.1]","auth":{"type":"bearer"}}}`, false},
		"origin-aws-metadata-v6":     {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"http://[fd00:ec2::254]","auth":{"type":"bearer"}}}`, false},
		"origin-numeric-name":        {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://example.127","auth":{"type":"bearer"}}}`, false},
		"origin-numeric-suffix-name": {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://example.127a","auth":{"type":"bearer"}}}`, true},
		"origin-octal-bad":           {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"http://09","auth":{"type":"bearer"}}}`, false},
		"origin-max-port":            {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"http://127.0.0.1:65535","auth":{"type":"bearer"}}}`, true},
		"origin-too-big-port":        {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"http://127.0.0.1:65536","auth":{"type":"bearer"}}}`, false},
		"origin-encoded-slash":       {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://www.example.test/%2f","auth":{"type":"bearer"}}}`, false},
		"origin-dotdot-subpath":      {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://www.example.test/%2e%2e/a","auth":{"type":"bearer"}}}`, false},
		"origin-literal-dotdot-sub":  {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"https://www.example.test/a/../../b","auth":{"type":"bearer"}}}`, false},
		"origin-doc-ipv4":            {`{"kind":"ask","text":"Key","credential":{"name":"k","origin":"http://192.0.2.1","auth":{"type":"bearer"}}}`, false},
		"otp-https-private":          {`{"kind":"ask","text":"Code","oneTimeCode":{"origin":"https://localhost"}}`, true},
		"otp-missing":                {`{"kind":"ask","text":"Code","oneTimeCode":{}}`, false},
		"import-need-local":          {`{"kind":"import_setup","items":[{"kind":"mcp","serverId":"s","name":"S","needs":[{"kind":"local_paths"}]}]}`, true},
		"import-need-missing-names":  {`{"kind":"import_setup","items":[{"kind":"mcp","serverId":"s","name":"S","needs":[{"kind":"env"}]}]}`, false},
		"otp-https":                  {`{"kind":"ask","text":"Code","oneTimeCode":{"origin":"https://www.example.test"}}`, true},
		"otp-http-localhost":         {`{"kind":"ask","text":"Code","oneTimeCode":{"origin":"http://localhost"}}`, false},
		"otp-path":                   {`{"kind":"ask","text":"Code","oneTimeCode":{"origin":"https://www.example.test/x"}}`, false},
		"otp-metadata":               {`{"kind":"ask","text":"Code","oneTimeCode":{"origin":"https://169.254.169.254"}}`, false},
		"import-model":               {`{"kind":"import_setup","items":[{"kind":"model","title":"M","provider":"p","providerName":"P"}]}`, true},
		"import-mcp":                 {`{"kind":"import_setup","items":[{"kind":"mcp","serverId":"s","name":"S","needs":[{"kind":"env","names":["A"]}]}]}`, true},
		"import-skill":               {`{"kind":"import_setup","items":[{"kind":"skill","name":"S","needs":[{"kind":"requires","names":["x"]}]}]}`, true},
		"import-unknown":             {`{"kind":"import_setup","items":[{"kind":"nope"}]}`, false},
		"import-missing-title":       {`{"kind":"import_setup","items":[{"kind":"model","provider":"p"}]}`, false},
		"import-undone":              {`{"kind":"import_setup","items":[],"undone":true}`, true},
		"list-valid-ask-plus-card":   {`[{"kind":"ask","text":"Allow?","status":"pending","approvalEffectId":"e"},{"kind":"text","text":"hi"}]`, true},
		"list-malformed-nested-cred": {`[{"kind":"ask","text":"Allow?","status":"pending","approvalEffectId":"e","credential":{"name":"site_key","origin":"https://www.example.test","auth":{"type":"header","name":"Host"}}}]`, false},
	}
	for name, test := range cases {
		t.Run(name, func(t *testing.T) {
			var value any
			if err := json.Unmarshal([]byte(test.json), &value); err != nil {
				t.Fatalf("fixture json: %v", err)
			}
			entries, isList := value.([]any)
			if !isList {
				entries = []any{value}
			}
			_, valid := ParseBlocks(entries)
			if valid != test.want {
				t.Fatalf("ParseBlocks valid = %v, want %v (zod fixture)", valid, test.want)
			}
		})
	}
}

func TestParseBlocksDropsTheWholeListOnOneInvalidEntry(t *testing.T) {
	malformed := []any{
		map[string]any{"kind": "text", "text": "hi"},
		map[string]any{"kind": "card", "lines": []any{map[string]any{"k": "missing v"}}},
	}
	if _, ok := ParseBlocks(malformed); ok {
		t.Fatal("a malformed card must make the list unparseable")
	}
}
